package org.lira.receiver;
import org.json.*;import java.nio.file.*;import java.io.*;import java.security.*;
public final class DictationRecognitionNavigationTest{
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
  JSONObject task=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));JSONArray rec=task.getJSONArray("phases").getJSONObject(0).getJSONArray("items"),targets=task.getJSONArray("lessons").getJSONObject(0).getJSONArray("two_targets");
  for(String ch:new String[]{"湖","山","川","云","林","风","雨","日","月","星","水","石","田","土","花","草"}){targets.put(ch);rec.put(new JSONObject().put("item_id","r-"+ch.codePointAt(0)).put("lesson_id","lesson-1").put("text",ch).put("covers",new JSONArray().put(ch)).put("audio_asset_id",JSONObject.NULL));}
  task.getJSONObject("playback").put("repeat_count",1).put("manual_navigation",true);byte[] pcm={1,0};StringBuilder sha=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(pcm))sha.append(String.format("%02x",b&255));task.getJSONArray("audio_assets").getJSONObject(0).put("sha256",sha.toString());task.put("content_hash",DictationSpec.contentHash(task));
  File dir=Files.createTempDirectory("recognition-navigation").toFile();TaskAssetStore assets=new TaskAssetStore(new File(dir,"assets"));String tid=task.getString("task_id"),hash=task.getString("content_hash");assets.begin(tid,hash,"audio-2",2,sha.toString());assets.append(tid,hash,"audio-2",0,pcm);assets.commit(tid,hash,"audio-2");
  JSONObject manifest=new JSONObject().put("task_id",tid).put("content_hash",hash).put("assets",new JSONArray().put(new JSONObject().put("asset_id","audio-2").put("sha256",sha.toString()).put("pcm_bytes",2).put("frames",1).put("sample_rate",24000).put("channels",1)));
  DictationEngineTest.Sound sound=new DictationEngineTest.Sound();final StringBuilder display=new StringBuilder();DictationEngine engine=new DictationEngine(new DictationEngineTest.Time(),sound,(k,w,t)->{display.setLength(0);display.append(t);},new DictationStateStore(new File(dir,"state")),assets);engine.displaySize(640,480);engine.start(new JSONObject().put("task",task).put("manifest",manifest).put("run_epoch",1));
  check(DictationRemote.action(engine.status(),23,0)==null,"recognition confirm does nothing even before start");check(DictationRemote.action(engine.status(),22,0).equals("start"),"right starts recognition");engine.localControl("start");int end=engine.status().getInt("page_end");check(end<rec.length()-1,"multiple pages precondition");check(end<2,"small screens limit each page to two large words");
  check(DictationRemote.action(engine.status(),23,0)==null,"recognition confirm never changes page");engine.localControl("previous");check(engine.status().getInt("index")==0,"first page left clamps");engine.localControl("confirm");check(engine.status().getInt("index")==end+1,"right next page");engine.localControl("previous");check(engine.status().getInt("index")==0,"left previous page restores first cursor");
  engine.setDebug(true);check(display.toString().contains("#"),"backend debug true exposes safe event log");engine.toggleDebug();check(engine.status().getBoolean("debug_enabled"),"local menu cannot override backend");engine.setDebug(false);check(!display.toString().contains("#")&&!engine.status().getBoolean("debug_enabled"),"backend false removes event log");
  while(engine.status().getJSONArray("steps").getJSONObject(engine.status().getInt("index")).getString("kind").equals("recognition"))engine.localControl("confirm");sound.drain();JSONObject p=DictationPresentation.describe(engine.status());check(p.getInt("ordinal")==1&&p.getInt("total")==1,"dictation progress counts only words, not recognition items");check(!p.toString().contains("/"),"child copy contains no fractional counters");check(!p.toString().contains(task.getJSONArray("phases").getJSONObject(1).getJSONArray("items").getJSONObject(0).getString("text")),"child copy never exposes dictated answer");
  System.out.println("Recognition left/right pages, no center, phase-local child progress, backend-only debug passed");
 }
}
